function splitLines(t){ return String(t||'').split(/\n+/).map(function(s){return s.trim();}).filter(function(s){return s.length;}); }
function sevRank(s){ return ({'严重':1,'高':2,'中':3,'低':4})[s]||3; }
function buildBugReport(o){
  o=o||{};
  var title=String(o.title||'').trim()||'（待填写缺陷标题）';
  var severity=String(o.severity||'中').trim();
  if(!{'严重':1,'高':2,'中':3,'低':4}[severity]) severity='中';
  var env=String(o.env||'').trim()||'（待补充环境）';
  var version=String(o.version||'').trim()||'（待补充版本）';
  var steps=splitLines(o.steps);
  var expected=String(o.expected||'').trim()||'（待填写期望结果）';
  var actual=String(o.actual||'').trim()||'（待填写实际结果）';
  var reporter=String(o.reporter||'').trim()||'（匿名）';
  var lines=[];
  lines.push('# Bug 报告：'+title);
  lines.push('');
  lines.push('- 严重度：'+severity+'（P'+sevRank(severity)+'）');
  lines.push('- 环境：'+env);
  lines.push('- 版本：'+version);
  lines.push('- 报告人：'+reporter);
  lines.push('');
  lines.push('## 复现步骤');
  if(steps.length){ steps.forEach(function(s,i){ lines.push((i+1)+'. '+s); }); }
  else { lines.push('1. （待补充复现步骤）'); }
  lines.push('');
  lines.push('## 期望结果');
  lines.push(expected);
  lines.push('');
  lines.push('## 实际结果');
  lines.push(actual);
  lines.push('');
  lines.push('## 附加信息');
  lines.push('- 是否必现：待确认');
  lines.push('- 日志 / 截图：待补充');
  return {title:title, severity:severity, prank:sevRank(severity), stepCount:steps.length, markdown:lines.join('\n')};
}
var EXPORTS={splitLines:splitLines, sevRank:sevRank, buildBugReport:buildBugReport};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.BugReportForgePure = EXPORTS; }
